//! php-src's `DateTime` diff/days/add/sub suite (`DateTime_*-{spring,fall}-type*`,
//! `rfc-datetime_and_daylight_saving_time-*`, ...), replayed from
//! `tests/data/dst_suite.txt` (generated by `tools/gen_dst_suite.py` from the
//! `.inc` data files and the `.phpt` expectations).

use std::collections::HashMap;
use std::fmt::Write as _;
use std::fs;
use std::path::Path;
use std::sync::Arc;

use php_date::api;
use php_date::parse::TimezoneSpec;
use php_date::{tz, Time, TzInfo};

const NOW: i64 = 1_136_073_600;

fn new_dt(s: &str, tz: &Arc<TzInfo>) -> Time {
    api::date_initialize(s.as_bytes(), None, None, tz, NOW, 0)
        .0
        .expect("valid date")
}

fn fmt(t: &Time, f: &str) -> String {
    String::from_utf8_lossy(&api::format(t, f.as_bytes())).into_owned()
}

fn get(vars: &HashMap<String, Time>, arg: &str, tz: &Arc<TzInfo>) -> (Option<String>, Time) {
    if let Some(name) = arg.strip_prefix('$') {
        (Some(name.to_string()), vars[name].clone())
    } else {
        (None, new_dt(arg, tz))
    }
}

fn run_case(mode: &str, script: &[&str]) -> String {
    let mut out = String::new();
    let mut zone = tz::get("UTC").unwrap();
    let mut vars: HashMap<String, Time> = HashMap::new();
    for line in script {
        let f: Vec<&str> = line.split('\t').collect();
        match f[0] {
            "tz" => zone = tz::get(f[1]).unwrap(),
            "echo" => out.push_str(f[1]),
            "new" => {
                let t = if f[2].is_empty() {
                    new_dt("now", &zone)
                } else {
                    new_dt(f[2], &zone)
                };
                vars.insert(f[1].to_string(), t);
            }
            "settz" => {
                let z = TimezoneSpec::Id(tz::get(f[2]).unwrap());
                api::set_timezone(vars.get_mut(f[1]).unwrap(), &z);
            }
            "setdate" => {
                let n: Vec<i64> = f[2..5].iter().map(|v| v.parse().unwrap()).collect();
                api::set_date(vars.get_mut(f[1]).unwrap(), n[0], n[1], n[2]);
            }
            "settime" => {
                let n: Vec<i64> = f[2..5].iter().map(|v| v.parse().unwrap()).collect();
                api::set_time(vars.get_mut(f[1]).unwrap(), n[0], n[1], n[2], 0);
            }
            "examine" => {
                let (end_var, mut end) = get(&vars, f[1], &zone);
                let (start_var, mut start) = get(&vars, f[2], &zone);
                let spec = f[3];
                let absolute = f[5] == "true";
                let start_date = fmt(&start, "Y-m-d H:i:s T");
                let end_date = fmt(&end, "Y-m-d H:i:s T");
                let mut iv = api::interval_from_iso(format!("P{}", &spec[2..]).as_bytes()).unwrap();
                if &spec[1..2] == "-" {
                    iv.rel.invert = 1;
                }
                match mode {
                    "DIFF" => {
                        let r = api::diff(&start, &end, absolute);
                        let spec = String::from_utf8_lossy(&r.format(b"P%R%yY%mM%dDT%hH%iM%sS"))
                            .into_owned();
                        let _ = writeln!(out, "DIFF: {end_date} - {start_date} = **{spec}**");
                    }
                    "DAYS" => {
                        let r = api::diff(&start, &end, absolute);
                        let days = String::from_utf8_lossy(&r.format(b"%a")).into_owned();
                        let _ = writeln!(out, "DAYS: **{days}**");
                    }
                    "ADD" => {
                        start = api::add(&start, &iv);
                        let _ = writeln!(
                            out,
                            "ADD: {start_date} + {spec} = **{}**",
                            fmt(&start, "Y-m-d H:i:s T")
                        );
                    }
                    "SUB" => {
                        end = api::sub(&end, &iv).unwrap();
                        let _ = writeln!(
                            out,
                            "SUB: {end_date} - {spec} = **{}**",
                            fmt(&end, "Y-m-d H:i:s T")
                        );
                    }
                    _ => unreachable!(),
                }
                if let Some(v) = end_var {
                    vars.insert(v, end);
                }
                if let Some(v) = start_var {
                    vars.insert(v, start);
                }
            }
            other => panic!("unknown op {other}"),
        }
    }
    out
}

/// `run-tests.php`-style `%s` / `%d` matching.
fn expectf_match(pattern: &str, text: &str) -> bool {
    fn m(p: &[u8], t: &[u8]) -> bool {
        if p.is_empty() {
            return t.is_empty();
        }
        if p.len() >= 2 && p[0] == b'%' && (p[1] == b's' || p[1] == b'd') {
            let ok = |c: u8| {
                if p[1] == b's' {
                    c != b'\n'
                } else {
                    c.is_ascii_digit()
                }
            };
            let mut n = 0;
            while n < t.len() && ok(t[n]) {
                n += 1;
                if m(&p[2..], &t[n..]) {
                    return true;
                }
            }
            return false;
        }
        !t.is_empty() && p[0] == t[0] && m(&p[1..], &t[1..])
    }
    m(pattern.as_bytes(), text.as_bytes())
}

#[test]
fn datetime_dst_suite() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/dst_suite.txt");
    let data = fs::read_to_string(path).unwrap();
    let mut lines = data.lines();
    let mut failures = Vec::new();
    let mut cases = 0;
    while let Some(head) = lines.next() {
        let h: Vec<&str> = head.split('\t').collect();
        assert_eq!(h[0], "#case");
        let (name, mode) = (h[1], h[2]);
        let mut script = Vec::new();
        let mut kind = "";
        for l in lines.by_ref() {
            if l == "#expect" || l == "#expectf" {
                kind = l;
                break;
            }
            script.push(l);
        }
        let mut expect = Vec::new();
        for l in lines.by_ref() {
            if l == "#end" {
                break;
            }
            expect.push(l);
        }
        let expect = expect.join("\n").trim().to_string();
        let got = run_case(mode, &script);
        let got = got.trim();
        let ok = if kind == "#expectf" {
            expectf_match(&expect, got)
        } else {
            expect == got
        };
        cases += 1;
        if !ok {
            let diff: Vec<String> = expect
                .lines()
                .zip(got.lines())
                .filter(|(a, b)| a != b)
                .take(5)
                .map(|(a, b)| format!("  want: {a}\n  got:  {b}"))
                .collect();
            failures.push(format!("{name}:\n{}", diff.join("\n")));
        }
    }
    assert_eq!(cases, 45);
    assert!(
        failures.is_empty(),
        "{} cases failed:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
